"use client";
import Image from "next/image";import {motion,useScroll,useTransform} from "framer-motion";import {useRef} from "react";import {ArrowDown,ArrowUpRight} from "lucide-react";import {site} from "@/data/site";
export default function Hero(){const ref=useRef<HTMLElement>(null);const {scrollYProgress}=useScroll({target:ref,offset:["start start","end start"]});const y=useTransform(scrollYProgress,[0,1],[0,140]),scale=useTransform(scrollYProgress,[0,1],[1,1.08]),textY=useTransform(scrollYProgress,[0,1],[0,-80]);return <section id="top" ref={ref} className="hero"><motion.div className="hero-image" style={{y,scale}}><Image src="/images/hero/diceys-night.png" alt="A lively evening at Dicey's" fill priority sizes="100vw"/></motion.div><div className="hero-shade"/><div className="grain"/><motion.div className="hero-content" style={{y:textY}}><motion.p initial={{opacity:0}} animate={{opacity:1}} transition={{delay:.3}} className="hero-eyebrow">Golf Club Road <i/> Bengaluru</motion.p><h1><motion.span initial={{y:"110%"}} animate={{y:0}} transition={{duration:1,ease:[.16,1,.3,1]}}>Good Food</motion.span><motion.span initial={{y:"110%"}} animate={{y:0}} transition={{duration:1,delay:.12,ease:[.16,1,.3,1]}}>Better <em>Pours</em></motion.span></h1><motion.p className="hero-copy" initial={{opacity:0,y:15}} animate={{opacity:1,y:0}} transition={{delay:.7}}>A place for good food, better pours and<br/>nights worth remembering.</motion.p><motion.div className="hero-actions" initial={{opacity:0}} animate={{opacity:1}} transition={{delay:.9}}><a className="button primary" href="#experience">Explore Dicey&apos;s <ArrowDown size={16}/></a><a className="button ghost" href={site.mapsUrl} target="_blank">Get directions <ArrowUpRight size={16}/></a></motion.div></motion.div><div className="hero-bottom"><a href="#story">Scroll to discover <ArrowDown size={14}/></a><p>Bengaluru <span>12.9716° N</span></p></div></section>}
